    """Slide each same-color connected object right until blocked."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            obj = []
            while stack:
                y, x = stack.pop()
                obj.append((y, x, color))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            objects.append(obj)
    objects.sort(key=lambda obj: max(x for y,x,v in obj), reverse=True)
    occupied = set()
    moved = []
    for obj in objects:
        shift = 0
        while True:
            candidate = {(y, x+shift+1) for y,x,v in obj}
            if any(x >= w or (y,x) in occupied for y,x in candidate):
                break
            shift += 1
        placed = [(y,x+shift,v) for y,x,v in obj]
        moved.append(placed)
        occupied.update((y,x) for y,x,v in placed)
    out = [[0] * w for _ in range(h)]
    for obj in moved:
